// Legacy canonical paths that have been superseded; redirect to the new path.
const LEGACY_REDIRECTS = {
  '/steh': '/seth',
  '/achilles': '/achilleus',
  '/aether': '/aither',
  '/delphi': '/delphoi',
  '/enki': '/ea',
  '/europa': '/europe',
  '/hercules': '/herakles',
  '/jason': '/iason',
  '/khaos': '/chaos',
  '/oceanus': '/okeanos',
  '/pegasus': '/pegasos',
};
// === END GENERATED LEXICON_IDS + LEGACY_REDIRECTS ===

export const config = {
  // Run on all paths except the Scholars API. Scholars uses vercel.json
  // rewrites to a single handler, and the middleware's fetch(request)
  // pass-through does not correctly dispatch to it.
  matcher: '/((?!api/v1/scholars/).*)',
};

export default function middleware(request) {
  const url = new URL(request.url);

  // ─── 0a. Force HTTPS ────────────────────────────────────────────────
  // Vercel's edge may receive plaintext requests; canonical content is
  // always served over HTTPS. We flip the protocol and continue so that
  // domain/path canonicalization happens in the same 301 hop.
  const needsHttpsRedirect = url.protocol === 'http:';
  if (needsHttpsRedirect) {
    url.protocol = 'https:';
  }

  // API routes: Vercel's trailingSlash:true issues a 308 redirect from
  // /api/v1/x to /api/v1/x/, which breaks CORS preflight and clients that
  // don't follow redirects (e.g. fetch without redirect:'follow').
  // Internally rewrite no-trailing-slash API calls to the slash version so
  // the function is invoked directly without a redirect.
  if (url.pathname.startsWith('/api/') && url.pathname.length > 1 && !url.pathname.endsWith('/')) {
    if (needsHttpsRedirect) {
      return new Response(null, {
        status: 301,
        headers: {
          'Location': url.toString(),
          'Cache-Control': 'public, max-age=0, must-revalidate',
        },
      });
    }
    const rewritten = new URL(request.url);
    rewritten.pathname += '/';
    return fetch(rewritten);
  }

  // Skip API routes — let Vercel Functions handle them
  if (url.pathname.startsWith('/api/')) {
    if (needsHttpsRedirect) {
      return new Response(null, {
        status: 301,
        headers: {
          'Location': url.toString(),
          'Cache-Control': 'public, max-age=0, must-revalidate',
        },
      });
    }
    return fetch(request);
  }

  // ─── 3b. /sites/{id} canonicalization ──────────────────────────────
  // The clean /{id}/ form is the canonical URL for every lexicon-entry
  // temple. Requests to the legacy /sites/{id}/ path 301 to the clean
  // form (subpath and trailing slash preserved; a trailing index.html
  // collapses to the slash form in the same hop).
  //
  // EXCEPTION: /sites/{id}/assets/* passes through untouched — the
  // vercel.json static-media proxy and absolute asset references depend
  // on the /sites/ prefix.
  if (url.pathname.startsWith('/sites/')) {
    const siteSegments = url.pathname.split('/').filter(Boolean); // ['sites', id, ...]
    const siteId = siteSegments[1];
    if (siteId && siteSegments[2] !== 'assets') {
      const legacyTarget = LEXICON_IDS.has(siteId)
        ? '/' + siteId
        : LEGACY_REDIRECTS['/' + siteId];
      if (legacyTarget) {
        let rest = url.pathname.slice(('/sites/' + siteId).length); // '', '/', '/lore/', ...
        if (rest === '' || rest === '/') {
          rest = '/';
        } else if (rest.endsWith('/index.html')) {
          rest = rest.slice(0, -'index.html'.length); // '/index.html' → '/', '/lore/index.html' → '/lore/'
        }
        url.pathname = legacyTarget + (rest === '/' ? '/' : rest);
        return new Response(null, {
          status: 301,
          headers: {
            'Location': url.toString(),
            'Cache-Control': 'public, max-age=0, must-revalidate',
          },
        });
      }
    }
  }

  // Redirect .html extension URLs to clean trailing-slash URLs. Vercel's
  // cleanUrls:true serves the file at the extensionless path, but it does not
  // 301 the .html variant, so both URLs can be crawled as duplicate content.
  if (url.pathname.endsWith('.html')) {
    let clean = url.pathname.slice(0, -5); // remove .html
    if (clean.endsWith('/index')) {
      clean = clean.slice(0, -5); // remove trailing /index
    }
    if (clean === '' || clean === '/') {
      clean = '/';
    } else if (!clean.endsWith('/')) {
      clean += '/';
    }
    url.pathname = clean;
    return new Response(null, {
      status: 301,
      headers: {
        'Location': url.toString(),
        'Cache-Control': 'public, max-age=0, must-revalidate',
      },
    });
  }

  // Normalize host: lowercase, strip port, trim whitespace
  const host = (request.headers.get('host') || '').toLowerCase().split(':')[0].trim();

  // ─── 0b. Defensive domains ─────────────────────────────────────────
  // punycodex.com (legacy brand) and www variants -> redirect to punicodex.com
  const DEFENSIVE_DOMAINS = new Set(['punycodex.com', 'www.punycodex.com', 'www.punicodex.com']);
  if (DEFENSIVE_DOMAINS.has(host)) {
    url.hostname = 'punicodex.com';
    return new Response(null, {
      status: 301,
      headers: {
        'Location': url.toString(),
        'Cache-Control': 'public, max-age=0, must-revalidate',
      },
    });
  }

  // Generic www. stripping for non-punicodex.com hosts before the domain-map
  // lookup. Defensive domains are handled above; this lets a single
  // DOMAIN_TO_ID entry cover both example.com and www.example.com.
  const lookupHost = host.startsWith('www.') ? host.slice(4) : host;

  // ─── 0. Direct-serve flagship domains ──────────────────────────────
  // Some deity domains should serve their temple page directly instead
  // of redirecting to punicodex.com/{id}.
  const DIRECT_SERVE_MAP = {
    'helheimr.com': 'helheimr',
    'www.helheimr.com': 'helheimr',
  };
  const directId = DIRECT_SERVE_MAP[lookupHost];
  if (directId) {
    if (needsHttpsRedirect) {
      return new Response(null, {
        status: 301,
        headers: {
          'Location': url.toString(),
          'Cache-Control': 'public, max-age=0, must-revalidate',
        },
      });
    }
    // Shared static assets live at the project root, not inside /sites/{id}.
    // Serve them from the root so root-relative links work: /js/...,
    // /css/..., the self-hosted webfonts (/assets/fonts/), and the brand
    // wordmark (/assets/brand/). Do NOT blanket-allow /assets/ — temple
    // pages reference mascots/composites relative to /sites/{id}/assets/,
    // and those depend on the prefixing below.
    if (/^\/(js|css)\//.test(url.pathname) || /^\/assets\/(fonts|brand)\//.test(url.pathname)) {
      return fetch(url);
    }
    url.pathname = '/sites/' + directId + url.pathname;
    return fetch(url);
  }

  // ─── 1. External-domain redirects ──────────────────────────────────
  // Some owned Unicode domains should redirect to another canonical domain
  // rather than serve the temple directly.
  const EXTERNAL_REDIRECT_DOMAINS = {
    'νίκη.com': 'https://punicodex.com/nike',
    'xn--kxaqik.com': 'https://punicodex.com/nike',
    'www.νίκη.com': 'https://punicodex.com/nike',
    'www.xn--kxaqik.com': 'https://punicodex.com/nike',
  };
  const externalTarget = EXTERNAL_REDIRECT_DOMAINS[lookupHost];
  if (externalTarget) {
    // Preserve path + query (νίκη.com/lore/?utm=x →
    // https://punicodex.com/nike/lore/?utm=x) so deep links and campaign
    // parameters survive the redirect to the canonical domain.
    return new Response(null, {
      status: 301,
      headers: {
        'Location': externalTarget + url.pathname + url.search,
        'Cache-Control': 'public, max-age=0, must-revalidate',
      },
    });
  }

  // ─── 2. Domain redirect ────────────────────────────────────────────
  // Unicode/punycode domains → 301 redirect to punicodex.com/{id}
  const id = DOMAIN_TO_ID[lookupHost];
  if (id) {
    url.hostname = 'punicodex.com';
    url.pathname = '/' + id + url.pathname;
    return new Response(null, {
      status: 301,
      headers: {
        'Location': url.toString(),
        'Cache-Control': 'public, max-age=0, must-revalidate',
      },
    });
  }

  // ─── 3. Legacy path redirects ──────────────────────────────────────
  // Superseded canonical paths → 301 redirect to the current canonical
  for (const [legacyPath, newPath] of Object.entries(LEGACY_REDIRECTS)) {
    if (url.pathname === legacyPath || url.pathname.startsWith(legacyPath + '/')) {
      url.pathname = url.pathname.replace(legacyPath, newPath);
      return new Response(null, {
        status: 301,
        headers: {
          'Location': url.toString(),
          'Cache-Control': 'public, max-age=0, must-revalidate',
        },
      });
    }
  }

  // Any remaining HTTP request has reached a non-redirect host/path and
  // should be redirected to HTTPS before we serve or rewrite internally.
  if (needsHttpsRedirect) {
    return new Response(null, {
      status: 301,
      headers: {
        'Location': url.toString(),
        'Cache-Control': 'public, max-age=0, must-revalidate',
      },
    });
  }

  // ─── 4. Temple clean-URL rewrite ───────────────────────────────────
  // punicodex.com/{id}/* → internally serves /sites/{id}/* for EVERY
  // lexicon entry (flagship and base temples alike).
  // URL stays as /{id}/* for clean SEO and UX
  const pathParts = url.pathname.split('/').filter(Boolean);
  const potentialId = pathParts[0];

  if (LEXICON_IDS.has(potentialId)) {
    const prefix = '/' + potentialId;
    if (url.pathname === prefix || url.pathname.startsWith(prefix + '/')) {
      url.pathname = '/sites' + url.pathname;
      return fetch(url);
    }
  }

  return fetch(request);
}
